M6_DECKS.push({ id: 'm6-en', fa: 'fa1', title: 'Enthalpy of neutralisation', dps: ['6.1.5'], cards: [
  { id: 'en01', dp: '6.1.5', t: 'con', q: 'Why are all neutralisation reactions exothermic?',
    a: L(['ΔH = enthalpy of products − enthalpy of reactants; for an exothermic reaction ΔH < 0.', 'Breaking bonds absorbs energy; making bonds releases energy.', 'Neutralisation is exothermic mainly because forming strong, stable bonds in H_2O releases more energy than it takes to break the bonds in the acid and base.']) },
  { id: 'en02', dp: '6.1.5', t: 'eq', q: 'What is the net ionic equation for a strong acid + strong base neutralisation in water?',
    a: E('H_3O^+(aq) + OH^-(aq) → 2H_2O(l)') + L(['Acids form H_3O^+ by donating a proton to water; bases form OH^- by accepting a proton from water.', 'A reaction between any strong acid and strong base always gives this net ionic equation.']) + N('A ‘strong’ acid or base completely dissociates (ionises) into its ions in water.') },
  { id: 'en03', dp: '6.1.5', t: 'eq', q: 'Write the full ionic and net ionic equations for HCl(aq) + NaOH(aq).',
    a: P('Full ionic equation:') + E('H^+(aq) + Cl^-(aq) + Na^+(aq) + OH^-(aq) → Na^+(aq) + Cl^-(aq) + H_2O(l)') + P('Na^+ and Cl^- are spectator ions. In water, H^+ exists as H_3O^+, so the net ionic equation is:') + E('H_3O^+(aq) + OH^-(aq) → 2H_2O(l)') },
  { id: 'en04', dp: '6.1.5', t: 'def', q: 'In q = mcΔT, what does each symbol mean, with units?',
    a: L(['<b>q</b>: quantity of heat absorbed by the solution (J)', '<b>m</b>: mass of the final solution (kg)', '<b>c</b>: specific heat capacity of the final solution, usually taken as water’s: 4.18 × 10^{3} J kg^{-1} K^{-1}', '<b>ΔT</b>: temperature change (K or °C)']) + P('A calorimeter is used to gather the data.') },
  { id: 'en05', dp: '6.1.5', t: 'def', q: 'In ΔH = −q/n, what is each term, and why is there a minus sign?',
    a: E('ΔH = ' + F('−q', 'n')) + L(['ΔH: enthalpy of neutralisation (kJ mol^{-1})', 'q: energy absorbed by the solution, in <b>kJ</b> (convert from J)', 'n: moles of <b>water produced</b>']) + P('The minus sign is needed because q is the energy absorbed by the solution, while ΔH is the energy released by neutralisation per mole of water formed.') + N('Experimental q is always too low because of unaccounted heat loss, so experimental ΔH differs from the theoretical value.') },
  { id: 'en06', dp: '6.1.5', t: 'exam', q: 'What are the key checks when calculating an enthalpy of neutralisation in an exam?',
    a: L(['m (mass of final solution) in kg', 'c in the right units: 4.18 × 10^{3} J kg^{-1} K^{-1}', 'Initial temperature = average of the two initial temperatures', 'Write equations before substituting', 'n = moles of water: find moles of each reactant (n = cV) and use the mole ratio to identify the limiting reagent', 'ΔH = −q/n, so your answer must be negative', 'Significant figures']) },
  { id: 'en07', dp: '6.1.5', t: 'calc', q: '50 mL of 2.0 M H_2SO_4 is mixed with 50 mL of 2.0 M NaOH. The temperature rises from 21.3 °C to 34.9 °C. Calculate q and ΔH (density 1 g mL^{-1}).',
    a: L(['ΔT = 34.9 − 21.3 = 13.6 K; V = 100 mL, so m = 0.100 kg', 'q = 0.100 × 4.18 × 10^{3} × 13.6 = 5684.8 J = 5.68 kJ', 'n(H_2SO_4) = n(NaOH) = 2.0 × 0.050 = 0.10 mol', 'H_2SO_4 + 2NaOH → Na_2SO_4 + 2H_2O: 1 : 2 ratio, so <b>NaOH is limiting</b>', 'n(H_2O) = n(NaOH) = 0.10 mol', 'ΔH = −5.6848 ÷ 0.10 = <b>−57 kJ mol^{-1}</b>']) + N('Sulfuric acid is diprotic, but there wasn’t enough NaOH to fully neutralise it. Theoretical value ≈ −57 kJ mol^{-1}.') },
  { id: 'en08', dp: '6.1.5', t: 'con', q: 'Why do strong acid + strong base neutralisations all have a very similar ΔH?',
    a: L(['Strong acids and bases fully dissociate, so OH^- and H^+ (H_3O^+) are already in solution.', 'Some energy is needed to overcome ion–water attractions, but more is released as bonds form in water, so the reaction is exothermic.', 'Every combination is the same net reaction, so ΔH ≈ −57 kJ mol^{-1} (e.g. NaOH + HNO_3: −57.3 kJ mol^{-1}).']) },
  { id: 'en09', dp: '6.1.5', t: 'con', q: 'Why is ΔH smaller (less negative) when a weak acid or weak base is neutralised?',
    a: L(['Weak acids and bases don’t fully dissociate.', 'Energy is required to ionise the weak acid or base.', 'So the overall reaction is not as exothermic.']) + P('Slide examples: strong base + weak acid, ΔH = −56.1 kJ mol^{-1}; strong base + very weak acid, ΔH = −11.7 kJ mol^{-1}.') },
  { id: 'en10', dp: '6.1.5', t: 'prac', q: 'Why is a Styrofoam cup used as the calorimeter instead of a metal container?',
    a: L(['Styrofoam is an insulator and absorbs only a small amount of heat from the system.', 'A metal container would absorb more heat, reducing the measured temperature change and giving a smaller calculated q.']) + N('Safety: wear goggles (acid and base are corrosive) and stir carefully so you don’t puncture the cup.') },
  { id: 'en11', dp: '6.1.5', t: 'con', q: 'Why does the amount of heat released depend on the limiting reagent?',
    a: P('Heat released depends on how many moles of reactants are converted to water. One reactant is usually limiting and the other is in excess, so the limiting reagent decides how many moles of water form, and therefore how much heat is released.') },
  { id: 'en12', dp: '6.1.5', t: 'exam', q: '2022 HSC: 100.0 mL of 0.50 M HCl was mixed with 100.0 mL of 0.50 M NaOH. A student found 2.6 × 10^{3} J of heat was released. Find ΔH in kJ mol^{-1}.',
    a: L(['n(H_2O) formed = n(HCl) reacted = 0.1000 × 0.50 = 0.050 mol', 'ΔH = −2.6 kJ ÷ 0.050 mol = <b>−52 kJ mol^{-1}</b>']) },
  { id: 'en13', dp: '6.1.5', t: 'prac', q: 'Prac 6.2: Outline the method for measuring an enthalpy of neutralisation.',
    a: OL(['Place the foam cup in a beaker for stability.', 'Measure 50 mL of acid into the foam cup.', 'Connect the temperature data logger and read the initial temperature.', 'Measure 50 mL of base into the cup.', 'Stir gently with the probe and record the maximum temperature reached.', 'Calculate ΔH per mole of water formed; repeat with other acid–base combinations.']) + N('Only the metal probe should touch liquids; wear safety glasses.') }
]});

