M6_DECKS.push({ id: 'm6-ph', fa: 'fa2', title: 'pH, pOH and the self-ionisation of water', dps: ['6.2.1', '6.2.2', '6.2.3'], cards: [
  { id: 'ph01', dp: '6.2.2', t: 'def', q: 'Define pH. What does a change of one pH unit mean?',
    a: E('pH = −log_{10}[H^+]') + L(['Calculated from [H^+] (more correctly [H_3O^+]); given on the HSC data sheet.', 'A negative logarithmic scale: each whole-number change is a factor of 10 in [H^+].', 'pH down 1 → [H^+] × 10; pH up 2 → [H^+] ÷ 100; pH down 6 → [H^+] × 10^{6}']), v: 'img:ph_scale' },
  { id: 'ph02', dp: '6.2.2', t: 'eq', q: 'How do you calculate [H^+] from a pH value? Is the formula on the data sheet?',
    a: E('[H^+] = 10^{−pH}') + L(['This one is <b>not</b> on the HSC data sheet.', 'pH has no units.', 'Use the log (log_{10}) button, not ln.']) },
  { id: 'ph03', dp: '6.2.2', t: 'calc', q: 'Find the pH of 1 M, 0.1 M and 10 M HCl.',
    a: L(['1 M: pH = −log(1) = <b>0</b>', '0.1 M: pH = −log(0.1) = <b>1</b>', '10 M: pH = −log(10) = <b>−1</b>']) + N('There’s no fixed limit to the pH scale apart from solubility: concentrated strong acids can have a negative pH, and concentrated strong bases can go beyond 14.') },
  { id: 'ph04', dp: '6.2.2', t: 'def', q: 'What are the significant-figure rules for pH calculations?',
    a: L(['[H^+] → pH: quote pH to as many <b>decimal places</b> as there are significant figures in [H^+]. E.g. [H^+] = 2.00 → pH 0.301; 2.56 × 10^{-9} → pH 8.592', 'pH → [H^+]: quote [H^+] to as many <b>significant figures</b> as there are decimal places in the pH. E.g. pH 1.32 → 4.8 × 10^{-2} mol L^{-1}; pH 11.32 → 4.8 × 10^{-12} mol L^{-1}']) },
  { id: 'ph05', dp: '6.2.2', t: 'eq', q: 'Describe the self-ionisation of water and state K_{w}.',
    a: E('H_2O(l) + H_2O(l) ⇌ H_3O^+(aq) + OH^-(aq)') + E('K_{w} = [H^+][OH^-] = 1.0 × 10^{-14} at 25 °C') + L(['Water is amphiprotic with a strong net dipole, so a small portion of molecules donate a proton to another water molecule.', 'The very small K_{w} shows the equilibrium lies very far to the left.', 'K_{w} is on the data sheet; it was determined using conductivity measurements.']) },
  { id: 'ph06', dp: '6.2.2', t: 'calc', q: 'Show why pure water at 25 °C has a pH of 7.',
    a: L(['In pure water [H^+] = [OH^-], so [H^+]^2 = 1.0 × 10^{-14}', '[H^+] = 1.0 × 10^{-7} mol L^{-1}', 'pH = −log(1.0 × 10^{-7}) = <b>7.0</b>']) + N('A neutral substance is defined as one where [H^+] = [OH^-].') },
  { id: 'ph07', dp: '6.2.2', t: 'con', q: 'A solution has [H^+] = 10^{-3} M. What is [OH^-]? What can change K_{w}?',
    a: L(['[OH^-] = <b>10^{-11} M</b>, because [H^+] × [OH^-] must equal 10^{-14}.', 'K_{w} stays constant in all aqueous solutions; it’s only affected by <b>temperature</b>.', 'If [H^+] or [OH^-] changes, the equilibrium re-establishes in line with K_{w}.']) },
  { id: 'ph08', dp: '6.2.2', t: 'def', q: 'Define pOH. How is it related to pH?',
    a: E('pOH = −log_{10}[OH^-]') + E('[OH^-] = 10^{−pOH}') + E('pH + pOH = 14 (at 25 °C)') + P('As pOH increases, pH decreases.') },
  { id: 'ph09', dp: '6.2.2', t: 'con', q: 'What are the two methods for calculating the pH of a strong base?',
    a: P('<b>Via pOH</b>:') + OL(['Find [OH^-] for the base.', 'pOH = −log[OH^-]', 'pH = 14 − pOH']) + P('<b>Via K_{w}</b> (first principles):') + OL(['Find [OH^-] for the base.', '[H^+] = K_{w} ÷ [OH^-]', 'pH = −log[H^+]']) + N('Be familiar with both.') },
  { id: 'ph10', dp: '6.2.2', t: 'calc', q: 'Calculate the pH of 0.25 M sodium hydroxide using both methods.',
    a: L(['[OH^-] = 0.25 mol L^{-1} (NaOH is strong)', 'Via pOH: pOH = −log(0.25) = 0.60, so pH = 14 − 0.60 = <b>13.40</b>', 'Via K_{w}: [H^+] = 1.0 × 10^{-14} ÷ 0.25 = 4.0 × 10^{-14}, so pH = −log(4.0 × 10^{-14}) = <b>13.40</b>']) },
  { id: 'ph11', dp: '6.2.2', t: 'calc', q: '(a) Find the pH when [H^+] = 1.0 × 10^{-4} M. (b) Find [H_3O^+] when the pH is 6.7.',
    a: L(['(a) pH = −log(1.0 × 10^{-4}) = <b>4.00</b> (2 sig figs in the concentration → 2 d.p.)', '(b) [H_3O^+] = 10^{-6.7} = <b>2 × 10^{-7} mol L^{-1}</b> (1 d.p. in the pH → 1 sig fig)']) },
  { id: 'ph12', dp: '6.2.2', t: 'calc', q: 'A solution has [H^+] = 1.0 × 10^{-7} M. Show whether it is acidic, basic or neutral.',
    a: L(['K_{w} = [H^+][OH^-] = 1.0 × 10^{-14}', '[OH^-] = 1.0 × 10^{-14} ÷ 1.0 × 10^{-7} = 1.0 × 10^{-7} M', '[H^+] = [OH^-], so it is <b>neutral</b>']) },
  { id: 'ph13', dp: '6.2.3', t: 'con', q: 'What three factors decide the [H_3O^+] (and pH) measured for an acid solution?',
    a: L(['Whether it’s <b>concentrated or dilute</b>', 'Whether the acid is <b>strong</b> (fully ionised) or <b>weak</b> (partially ionised)', 'How many protons it can donate: <b>monoprotic</b> (e.g. HCl) or <b>polyprotic</b> (e.g. H_2SO_4)']) + N('Polyprotic acids ionise step by step, each step weaker than the last, so the first step usually dictates the pH.') },
  { id: 'ph14', dp: '6.2.1', t: 'con', q: 'How does a pH probe work?',
    a: L(['A pair of electrodes: a <b>glass electrode</b> sensitive to H^+/H_3O^+ (a very fragile external bulb) and a <b>reference electrode</b> in saturated KCl solution.', 'Immersing the probe completes the circuit. The sensing electrode’s voltage changes with [H_3O^+]: the higher [H_3O^+], the more positive the voltage.', 'pH is calculated from the voltage difference between the sensing and reference electrodes.']), v: 'img:ph_probe' },
  { id: 'ph15', dp: '6.2.1', t: 'con', q: 'Why are pH probe results more valid than universal indicator results?',
    a: L(['Quantitative and more precise (2 d.p.)', 'Don’t depend on a person’s interpretation of colour', 'Can distinguish solutions with small differences in pH', 'More objective, if calibrated and rinsed between measurements', 'Don’t interfere with the sample’s chemistry or shift its equilibrium position, so they are non-destructive']) },
  { id: 'ph16', dp: '6.2.1', t: 'prac', q: 'Prac 6.3: What are the expected pH values of 0.10 M solutions of HCl, H_2SO_4, acetic acid, citric acid, ammonium hydroxide and NaOH? Which are weak?',
    a: L(['HCl 1.00; H_2SO_4 0.96', 'Acetic acid 2.88; citric acid 2.08 (<b>weak acids</b>)', 'Ammonium hydroxide 11.12 (<b>weak base</b>)', 'NaOH 13.00']) + N('At 0.1 M a strong monoprotic acid has pH ≈ 1 and a strong base pH ≈ 13. Strength relates to degree of ionisation; concentration relates to moles per litre.') },
  { id: 'ph17', dp: '6.2.1', t: 'con', q: 'Prac 6.3: Why is the pH of 0.10 M H_2SO_4 about 0.96, not 0.70?',
    a: L(['0.10 M HCl is monoprotic: [H^+] = 0.10 M, pH = 1.00', 'If both protons of H_2SO_4 fully ionised: [H^+] = 0.20 M, pH = 0.70', 'In reality the second ionisation isn’t complete, so [H^+] < 0.20 M and the pH falls between 0.70 and 1.00']) },
  { id: 'ph18', dp: '6.2.1', t: 'calc', q: '0.10 M acetic acid is 1.3% ionised in water. Calculate its pH.',
    a: L(['[H^+] = 0.10 × 0.013 = 1.3 × 10^{-3} mol L^{-1}', 'pH = −log(1.3 × 10^{-3}) = <b>2.89</b>']) + N('The class pH probe measured 2.97, close to the theoretical value.') }
]});

