M6_DECKS.push({ id: 'm6-sc', fa: 'fa2', title: 'Strength, conjugates and amphiprotic species', dps: ['6.2.3', '6.2.4', '6.2.5'], cards: [
  { id: 'sc01', dp: '6.2.3', t: 'def', q: 'What does the ‘strength’ of an acid or base describe, and how is it shown in equations?',
    a: L(['Strength = the <b>degree of ionisation</b> in water.', '<b>Strong</b>: ionises completely; single arrow (→), e.g. HCl(aq) → H^+(aq) + Cl^-(aq). ‘Strong’ isn’t a spectrum: all strong acids ionise completely.', '<b>Weak</b>: ionises partially; reversible arrow (⇌), reaching dynamic equilibrium that lies far to the left, e.g. CH_3COOH ⇌ H^+ + CH_3COO^-. ‘Weak’ is a spectrum: a larger K_{a} or K_{b} means more ionisation.']) },
  { id: 'sc02', dp: '6.2.5', t: 'con', q: 'Distinguish strength from concentration, with examples.',
    a: L(['Concentration = how many moles of acid or base are dissolved in a known volume (molarity): concentrated or dilute.', '<b>Strong ≠ concentrated; weak ≠ dilute.</b>', '0.001 M HCl is a dilute solution of a strong acid.', '5 M NH_3 is a concentrated solution of a weak base.']), v: 'particles' },
  { id: 'sc03', dp: '6.2.5', t: 'rec', q: 'Which common acids and bases must you memorise as strong or weak?',
    a: L(['<b>Strong acids</b>: hydrochloric, sulfuric, nitric, hydrobromic, hydroiodic', '<b>Strong bases</b>: metal hydroxides, e.g. sodium, potassium, lithium and calcium hydroxide', '<b>Weak acids</b>: carbonic, phosphoric, hydrofluoric, carboxylic acids (e.g. ethanoic, citric)', '<b>Weak bases</b>: ammonia, amines, amides']) },
  { id: 'sc04', dp: '6.2.5', t: 'con', q: 'Why might calcium hydroxide appear to be a weak base?',
    a: P('Calcium hydroxide is a strong base but has <b>low solubility</b> (limited by K_{sp}). Only a small amount dissolves, though what does dissolve dissociates completely, so the pH may not be as high as you’d expect for a strong base.') },
  { id: 'sc05', dp: '6.2.4', t: 'def', q: 'What is the difference between ionisation and dissociation?',
    a: L(['<b>Ionisation</b>: ions are formed, e.g. HCl(g) + H_2O(l) → H_3O^+(aq) + Cl^-(aq)', '<b>Dissociation</b>: existing ions split apart, e.g. NaOH(s) → Na^+(aq) + OH^-(aq)']) + N('The HSC syllabus and many texts call acid ionisation ‘dissociation’.') },
  { id: 'sc06', dp: '6.2.4', t: 'def', q: 'What is a conjugate acid–base pair? Identify the pairs when HCl and NH_3 react with water.',
    a: P('An acid that donates a proton leaves its <b>conjugate base</b>; a base that accepts a proton becomes its <b>conjugate acid</b>. Pairs differ by exactly one H^+.') + E('HCl + H_2O → H_3O^+ + Cl^-') + P('Pairs: HCl/Cl^- and H_3O^+/H_2O') + E('NH_3 + H_2O ⇌ OH^- + NH_4^+') + P('Pairs: NH_4^+/NH_3 and H_2O/OH^-') },
  { id: 'sc07', dp: '6.2.4', t: 'con', q: 'How does the strength of an acid relate to the strength of its conjugate base?',
    a: L(['The stronger an acid, the weaker its conjugate base; the stronger a base, the weaker its conjugate acid.', 'HCl is strong, so Cl^- is a very weak base: it almost never pulls an H^+ off water to re-form HCl.', 'A weak acid has a weak conjugate base: CH_3COO^- can accept a proton a little, but not enough to be a strong base.']) },
  { id: 'sc08', dp: '6.2.5', t: 'con', q: 'Explain how phenolphthalein works using its equilibrium.',
    a: E('HIn (colourless) ⇌ H^+ + In^- (pink)') + L(['Indicators are usually weak acids or bases, so they set up a dynamic equilibrium in water.', 'In acid: the added H^+ drives the equilibrium left; In^- is used up and the mixture is colourless.', 'In alkali: [H^+] is low, driving the equilibrium right; more In^- forms and the mixture turns pink.']) },
  { id: 'sc09', dp: '6.2.5', t: 'con', q: 'How does the colour of bromothymol blue depend on protonation?',
    a: L(['At acidic pH, BTB <b>accepts</b> a proton: protonated BTB is <b>yellow</b>.', 'At basic pH, BTB <b>donates</b> a proton: deprotonated BTB is <b>blue</b>.']) },
  { id: 'sc10', dp: '6.2.4', t: 'def', q: 'Define monoprotic, diprotic and triprotic acids, with examples.',
    a: L(['An acidic hydrogen is one in a highly polar bond, liable to be lost as H^+.', '<b>Monoprotic</b>: one acidic hydrogen, e.g. hydrochloric acid', '<b>Diprotic</b>: two, e.g. sulfuric acid', '<b>Triprotic</b>: three, e.g. phosphoric acid', 'More than one acidic hydrogen = <b>polyprotic</b>']), v: 'img:protic' },
  { id: 'sc11', dp: '6.2.4', t: 'eq', q: 'Write the stepwise ionisation of sulfuric acid in water.',
    a: E('H_2O(l) + H_2SO_4(aq) → H_3O^+(aq) + HSO_4^-(aq)') + E('H_2O(l) + HSO_4^-(aq) ⇌ H_3O^+(aq) + SO_4^{2-}(aq)') + L(['The conjugate base formed in step 1 is the acid in step 2.', 'The first hydrogen ionises completely; the second only partially.', 'In almost all calculations, treat sulfuric acid as a strong diprotic acid (both protons fully ionised).']) },
  { id: 'sc12', dp: '6.2.4', t: 'eq', q: 'Write the stepwise ionisation equations for phosphoric acid.',
    a: E('H_3PO_4(aq) + H_2O(l) ⇌ H_2PO_4^-(aq) + H_3O^+(aq)') + E('H_2PO_4^-(aq) + H_2O(l) ⇌ HPO_4^{2-}(aq) + H_3O^+(aq)') + E('HPO_4^{2-}(aq) + H_2O(l) ⇌ PO_4^{3-}(aq) + H_3O^+(aq)') + P('Overall: H_3PO_4 + 3H_2O ⇌ PO_4^{3-} + 3H_3O^+') },
  { id: 'sc13', dp: '6.2.4', t: 'rec', q: 'Give the formulae of hydrogen sulfate, hydrogen carbonate, dihydrogen phosphate and hydrogen phosphate.',
    a: L(['hydrogen sulfate: HSO_4^-', 'hydrogen carbonate: HCO_3^-', 'dihydrogen phosphate: H_2PO_4^-', 'hydrogen phosphate: HPO_4^{2-}']) + N('These are the conjugate bases of common polyprotic acids.') },
  { id: 'sc14', dp: '6.2.4', t: 'def', q: 'What is an amphiprotic substance? Show water acting as one.',
    a: P('A substance that can <b>accept or donate</b> a proton, depending on its chemical environment. The simplest proof is two equations: one with HCl, one with ammonia.') + E('H_2O(l) + HCl(aq) → H_3O^+(aq) + Cl^-(aq)') + P('Water acts as a base (accepts H^+).') + E('H_2O(l) + NH_3(aq) ⇌ OH^-(aq) + NH_4^+(aq)') + P('Water acts as an acid (donates H^+).') },
  { id: 'sc15', dp: '6.2.4', t: 'eq', q: 'Show that sodium hydrogen carbonate (NaHCO_3) is amphiprotic.',
    a: P('NaHCO_3 dissociates into Na^+ and HCO_3^-; the HCO_3^- is amphiprotic.') + E('HCO_3^-(aq) + HCl(aq) ⇌ H_2CO_3(aq) + Cl^-(aq)') + P('Acts as a base with a stronger acid.') + E('HCO_3^-(aq) + NH_3(aq) ⇌ CO_3^{2-}(aq) + NH_4^+(aq)') + P('Acts as an acid with a stronger base.') },
  { id: 'sc16', dp: '6.2.4', t: 'eq', q: 'Show that potassium dihydrogen phosphate (KH_2PO_4) is amphiprotic.',
    a: P('KH_2PO_4 ionises to K^+ and H_2PO_4^-; the H_2PO_4^- is amphiprotic.') + E('H_2PO_4^-(aq) + HCl(aq) ⇌ H_3PO_4(aq) + Cl^-(aq)') + P('Acting as a base. H_3PO_4 can’t accept another proton, so H_2PO_4^- isn’t dibasic.') + E('H_2PO_4^-(aq) + NH_3(aq) ⇌ HPO_4^{2-}(aq) + NH_4^+(aq)') + P('Acting as an acid. HPO_4^{2-} could donate another proton to become PO_4^{3-}, so it’s diprotic.') },
  { id: 'sc17', dp: '6.2.4', t: 'eq', q: 'Write equations for HNO_3, HF and HSO_4^- ionising in water, and for HPO_4^{2-} acting as a base.',
    a: E('HNO_3(aq) + H_2O(l) → H_3O^+(aq) + NO_3^-(aq)') + E('HF(aq) + H_2O(l) ⇌ H_3O^+(aq) + F^-(aq)') + E('HSO_4^-(aq) + H_2O(l) ⇌ H_3O^+(aq) + SO_4^{2-}(aq)') + E('HPO_4^{2-}(aq) + H_2O(l) ⇌ H_2PO_4^-(aq) + OH^-(aq)') + N('Strong HNO_3 gets a single arrow; the weak species get ⇌.') },
  { id: 'sc18', dp: '6.2.4', t: 'con', q: 'Is citric acid monoprotic or polyprotic? Explain.',
    a: P('<b>Triprotic</b>: it has three carboxylic acid groups, each of which can donate an H^+. It can also be called polyprotic, the more general term.') }
]});

