M6_DECKS.push({ id: 'm6-dm', fa: 'fa2', title: 'pH of diluted and mixed solutions', dps: ['6.2.6'], cards: [
  { id: 'dm01', dp: '6.2.6', t: 'con', q: 'How do you find the pH of a diluted strong acid or base?',
    a: L(['Use C_1V_1 = C_2V_2 to find the new [H_3O^+] or [OH^-].', 'Substitute into the pH (or pOH) equation.']) + N('Diluted weak acids and bases need K_{a}/K_{b}, covered later in the topic.') },
  { id: 'dm02', dp: '6.2.6', t: 'calc', q: 'Find the pH of a solution made by diluting 35.0 mL of 4.5 M HNO_3 to 2.25 L.',
    a: L(['C_2 = C_1V_1 ÷ V_2 = (4.5 × 0.0350) ÷ 2.25 = 0.070 mol L^{-1}', 'HNO_3 is strong and monoprotic, so [H^+] = 0.070 M', 'pH = −log(0.070) = <b>1.15</b>']) },
  { id: 'dm03', dp: '6.2.6', t: 'calc', q: '100.0 mL of 18.0 M HCl is added to a 2 L volumetric flask and made up to the mark. What is the pH?',
    a: L(['C_2 = (18.0 × 0.1000) ÷ 2.000 = 0.900 mol L^{-1}', 'pH = −log(0.900) = <b>0.046</b>']) },
  { id: 'dm04', dp: '6.2.6', t: 'con', q: 'List the steps for finding the pH after an acid and a base are mixed.',
    a: OL(['Write a balanced equation for the neutralisation (if not given).', 'Calculate the initial moles of acid and base.', 'Use the mole ratio to identify the limiting reagent.', 'Calculate the moles of acid or base left over.', 'Use the dissociation mole ratio to find moles of H^+ or OH^-.', 'Find [H^+] or [OH^-] in the <b>total</b> volume of mixed solution.', 'Substitute into the pH equation (or pOH, then pH = 14 − pOH).']) + N('Common error: forgetting to use the new total volume.') },
  { id: 'dm05', dp: '6.2.6', t: 'calc', q: '25.0 mL of 0.200 M HCl is mixed with 40.0 mL of 0.100 M NaOH. Calculate the pH.',
    a: L(['HCl + NaOH → NaCl + H_2O', 'n(HCl) = 0.200 × 0.0250 = 0.00500 mol; n(NaOH) = 0.100 × 0.0400 = 0.00400 mol', '1 : 1 ratio, so NaOH is limiting and HCl is in excess', 'n(HCl) left = 0.00500 − 0.00400 = 0.00100 mol = n(H^+)', '[H^+] = 0.00100 ÷ (0.0250 + 0.0400) = 0.0154 mol L^{-1}', 'pH = −log(0.0154) = <b>1.812</b>']) },
  { id: 'dm06', dp: '6.2.6', t: 'calc', q: '50.0 mL of 0.100 M HCl is mixed with 25.0 mL of 0.200 M HNO_3. What is the resulting pH?',
    a: L(['For two acids, add the total moles of H^+ and use the total volume. <b>Averaging pH values doesn’t work.</b>', 'n(H^+) = (0.100 × 0.0500) + (0.200 × 0.0250) = 0.00500 + 0.00500 = 0.0100 mol', '[H^+] = 0.0100 ÷ 0.0750 = 0.133 mol L^{-1}', 'pH = −log(0.133) = <b>0.875</b>']) + N('NESA mixing questions only involve strong acids or bases; weak ones are too complex.') },
  { id: 'dm07', dp: '6.2.6', t: 'prac', q: 'Prac 6.3: What volume of 0.100 M solution is needed to make 40.0 mL of 0.0100 M solution?',
    a: L(['C_1V_1 = C_2V_2: 0.100 × V_1 = 0.0100 × 40.0', 'V_1 = <b>4.00 mL</b>', 'Transfer with a graduated pipette, top up to 40 mL with distilled water, stopper and invert to mix. Repeat to make a dilution series down to 0.00001 M.']) }
]});

/* ---------- Deck 8 ---------- */
M6_DECKS.push({ id: 'm6-tt', fa: 'fa3', title: 'Titration technique', dps: ['6.3.1'], cards: [
  { id: 'tt01', dp: '6.3.1', t: 'def', q: 'Distinguish qualitative from quantitative analysis. What is a titration?',
    a: L(['<b>Qualitative</b>: what substances are present. <b>Quantitative</b>: how much is present.', 'Volumetric analysis is a form of quantitative analysis; titration is the traditional method.', 'A standard solution (the <b>titrant</b>) reacts with a solution of unknown concentration (the <b>analyte</b>) by a reaction of known stoichiometry, so the unknown concentration can be found.']) },
  { id: 'tt02', dp: '6.3.1', t: 'def', q: 'Define aliquot, titre and concordant titres.',
    a: L(['<b>Aliquot</b>: an accurately known volume of solution (usually the unknown) delivered to the conical flask from a pipette.', '<b>Titre</b>: the volume of standard solution delivered from the burette.', '<b>Concordant titres</b>: repeated titres within a total range of 0.10 mL.']) },
  { id: 'tt03', dp: '6.3.1', t: 'def', q: 'Distinguish the end point from the equivalence point.',
    a: L(['<b>End point</b>: when the indicator shows a permanent colour change. Often a single drop causes it.', '<b>Equivalence point</b>: when only products remain. Exactly enough titrant has been added to match the mole ratio, so neither reactant is in excess.']) + P('A successful titration has the end point and equivalence point match. If the colour changes before all the analyte has reacted, the method is invalid and a different indicator is needed.') },
  { id: 'tt04', dp: '6.3.1', t: 'rec', q: 'Name the glassware used in titrations and what each is for.',
    a: L(['<b>Volumetric flask</b>: prepares a standard solution (measures to 5 sig figs)', '<b>Volumetric pipette</b>: accurately measures an aliquot of analyte into the conical flask (4 sig figs)', '<b>Burette</b>: delivers accurate but variable volumes (titres) of standard solution', '<b>Graduated pipette</b>: used instead of a volumetric pipette when the volume isn’t standard']), v: 'img:glassware' },
  { id: 'tt05', dp: '6.3.1', t: 'rec', q: 'What four things are needed to determine a concentration by titration?',
    a: L(['A standard solution of precisely known concentration that reacts with the unknown by a known reaction', 'The stoichiometry of the reaction (a balanced equation)', 'A way to tell when the reaction is complete, often an indicator', 'A way to accurately measure the volumes of titrant and analyte (volumetric glassware)']) },
  { id: 'tt06', dp: '6.3.1', t: 'prac', q: 'Outline the general procedure for an acid–base titration.',
    a: OL(['Pipette an aliquot of the analyte into a conical flask.', 'Add a few drops of a suitable indicator.', 'Fill the burette with standard solution and note the initial volume.', 'Add the standard slowly until the first permanent colour change.', 'Record the titre (final − initial).', 'Repeat until you have 3 concordant titres (within 0.10 mL).']) },
  { id: 'tt07', dp: '6.3.1', t: 'rec', q: 'How should each piece of glassware be rinsed before a titration?',
    a: L(['Volumetric flask: distilled water only (it’s topped up with water anyway)', 'Burette: distilled water, then the <b>titrant</b>', 'Pipette: distilled water, then the <b>analyte</b>', 'Conical flask: distilled water only (water doesn’t change the moles of analyte)']) },
  { id: 'tt08', dp: '6.3.1', t: 'con', q: 'Predict the effect on the calculated analyte concentration if: (a) the burette is rinsed only with water, (b) the pipette is rinsed only with water, (c) the conical flask is rinsed with analyte.',
    a: L(['(a) Residual water dilutes the standard, so a larger titre is needed: <b>overestimate</b>.', '(b) The aliquot is diluted, so it contains fewer moles of analyte: <b>underestimate</b>.', '(c) Extra moles of analyte are added, so a larger titre is needed: <b>overestimate</b>.']) },
  { id: 'tt09', dp: '6.3.1', t: 'con', q: 'How do you read a burette, and why are three concordant titres averaged?',
    a: L(['Read at the bottom of the meniscus.', 'Burettes are marked in 0.10 mL intervals; estimate to the nearest 0.02 mL.', 'One drop is about 0.05 mL, so averaging three titres within 0.10 mL assumes results are no more than one drop over or under the accurate titre.']) },
  { id: 'tt10', dp: '6.3.1', t: 'calc', q: 'Titres (mL): 20.20, 19.82, 19.64, 19.78, 19.86. Which are concordant, and what is the average titre?',
    a: L(['Concordant: <b>19.82, 19.78 and 19.86</b> (range 19.86 − 19.78 = 0.08 mL, within 0.10 mL)', '20.20 and 19.64 fall outside that range', 'Average = (19.82 + 19.78 + 19.86) ÷ 3 = <b>19.82 mL</b>']) },
  { id: 'tt11', dp: '6.3.1', t: 'con', q: 'Once you have an average titre, how do you calculate the analyte concentration?',
    a: OL(['Moles of standard = c × average titre volume', 'Use the mole ratio to find moles of unknown reacted', 'Concentration = moles ÷ aliquot volume']) },
  { id: 'tt12', dp: '6.3.1', t: 'calc', q: '25.0 mL of NaOH is neutralised by 20.0 mL of 0.10 M HCl. Determine [NaOH].',
    a: L(['HCl(aq) + NaOH(aq) → NaCl(aq) + H_2O(l); ratio 1 : 1', 'n(HCl) = 0.10 × 0.0200 = 2.00 × 10^{-3} mol', 'n(NaOH) = 2.00 × 10^{-3} mol at the equivalence point', 'c(NaOH) = 2.00 × 10^{-3} ÷ 0.0250 = <b>0.080 mol L^{-1}</b>']) }
]});

/* ---------- Deck 9 ---------- */
M6_DECKS.push({ id: 'm6-ss', fa: 'fa3', title: 'Standard solutions, pracs and back titrations', dps: ['6.3.1', '6.3.6'], cards: [
  { id: 'ss01', dp: '6.3.1', t: 'def', q: 'What is a primary standard? List the properties it needs, with two examples.',
    a: P('A substance that can be weighed accurately and used to prepare a solution of exactly known concentration. It must:') + L(['have very high purity', 'be stable in air (not absorb moisture or react with atmospheric gases)', 'have a relatively high molar mass (reduces % weighing error)', 'dissolve readily in water']) + P('Examples: sodium carbonate; potassium hydrogen phthalate, KH(C_8H_4O_4).') },
  { id: 'ss02', dp: '6.3.1', t: 'prac', q: 'Outline how to make a standard solution from a primary standard.',
    a: OL(['Weigh the pure solid on an electronic balance.', 'Transfer to a volumetric flask using a clean, dry funnel.', 'Rinse any remaining solid into the flask with deionised water.', 'Half-fill the flask, stopper it and swirl to dissolve.', 'Add deionised water up to the calibration line.', 'Stopper and shake to give an even concentration.']), v: 'img:std_soln' },
  { id: 'ss03', dp: '6.3.1', t: 'def', q: 'What is a secondary standard? Why must NaOH and HCl be standardised?',
    a: P('A solution whose concentration can’t be found accurately by weighing alone, so it’s standardised against a primary standard by titration. This is because the substance:') + L(['is impure', 'absorbs moisture from the air', 'reacts with carbon dioxide or oxygen', 'is volatile or unstable']) + P('Examples: sodium hydroxide, hydrochloric acid. A primary standard sets up an accurately known solution, which is then used to find the exact concentration of the secondary standard.') },
  { id: 'ss04', dp: '6.3.1', t: 'calc', q: 'What mass of Na_2CO_3 is needed to make 250.00 mL of a 0.0500 M standard solution?',
    a: L(['n = cV = 0.0500 × 0.25000 = 0.01250 mol', 'M(Na_2CO_3) = (2 × 22.99) + 12.01 + (3 × 16.00) = 105.99 g mol^{-1}', 'm = 0.01250 × 105.99 = <b>1.325 g</b>']) },
  { id: 'ss05', dp: '6.3.1', t: 'calc', q: 'What volume of 0.0500 M Na_2CO_3 reacts with 25.00 mL of 0.100 M HCl?',
    a: L(['Na_2CO_3 + 2HCl → 2NaCl + H_2O + CO_2', 'n(HCl) = 0.100 × 0.02500 = 0.00250 mol', 'n(Na_2CO_3) = 0.00250 ÷ 2 = 0.00125 mol', 'V = n ÷ c = 0.00125 ÷ 0.0500 = 0.0250 L = <b>25 mL</b>']) },
  { id: 'ss06', dp: '6.3.6', t: 'prac', q: 'Prac 6.4 and 6.5: Outline the chain of three titrations used to find the acetic acid content of vinegar.',
    a: OL(['Na_2CO_3 primary standard (titrant) vs HCl (analyte), <b>methyl orange</b>: strong acid / weak base. Finds the exact [HCl].', 'HCl (titrant) vs NaOH (analyte), <b>bromothymol blue</b>: strong acid / strong base. Standardises the NaOH.', 'NaOH (titrant) vs vinegar, CH_3COOH (analyte), <b>phenolphthalein</b>: weak acid / strong base.']) },
  { id: 'ss07', dp: '6.3.1', t: 'con', q: 'Why is methyl orange the indicator when titrating Na_2CO_3 against HCl?',
    a: L(['Carbonate accepts two protons in steps: CO_3^{2-} + H^+ → HCO_3^-, then HCO_3^- + H^+ → H_2CO_3', 'Some H_2CO_3 becomes dissolved CO_2 (H_2CO_3 ⇌ CO_2 + H_2O) and some ionises (H_2CO_3 ⇌ H^+ + HCO_3^-)', 'Carbonic acid is weak and partially ionises, so the equivalence point is acidic: pH ≈ 4', 'Methyl orange changes colour between pH 3.1 and 4.4']) },
  { id: 'ss08', dp: '6.3.6', t: 'con', q: 'Why is phenolphthalein the indicator when titrating vinegar with NaOH?',
    a: E('NaOH + CH_3COOH → NaCH_3COO + H_2O') + L(['Sodium acetate dissolves: NaCH_3COO → Na^+ + CH_3COO^-', 'Acetate ions are a weak base: CH_3COO^- + H_2O ⇌ CH_3COOH + OH^-', 'So the equivalence point is basic (pH ≈ 8.5–9), which suits phenolphthalein']) },
  { id: 'ss09', dp: '6.3.6', t: 'con', q: 'Why not titrate the acetic acid in vinegar directly with sodium carbonate?',
    a: P('It would be a <b>weak acid + weak base</b> titration. There’s no sharp pH change at the equivalence point, so no indicator would give a clear end point.') },
  { id: 'ss10', dp: '6.3.6', t: 'prac', q: 'Prac 6.5: Outline the procedure for analysing household vinegar.',
    a: OL(['Make a 1 : 10 volumetric dilution of vinegar in a 250 mL volumetric flask.', 'Rinse and fill the burette with the standardised NaOH.', 'Pipette a 25.00 mL aliquot of diluted vinegar into a conical flask on white paper.', 'Add three drops of phenolphthalein.', 'Titrate to a faint pink that doesn’t fade on swirling; intense pink means overshoot.', 'Record the titre to 2 d.p. and repeat until three titres are concordant.']) },
  { id: 'ss11', dp: '6.3.1', t: 'def', q: 'What is a back titration, and when is it used?',
    a: P('An indirect method: a known excess of reagent reacts with the sample, then the leftover reagent is titrated. Used when direct titration isn’t appropriate:') + L(['the reaction is too slow for a definite end point', 'the sample is insoluble in water but reacts with acid', 'the sample is toxic or volatile', 'the sample is a gas in a mixture of gases', 'the sample is fairly unreactive, or present at low or trace levels']), v: 'backbar' },
  { id: 'ss12', dp: '6.3.1', t: 'prac', q: 'Outline how a back titration finds the percentage of calcium carbonate in limestone.',
    a: E('CaCO_3(s) + 2HCl(aq) → CaCl_2(aq) + CO_2(g) + H_2O(l)') + OL(['React a known excess of standardised HCl with the CaCO_3 (it’s insoluble, so can’t be titrated directly).', 'Heat to make sure all the CaCO_3 reacts.', 'Titrate the remaining HCl with standardised NaOH.', 'Use the NaOH titre to find moles of HCl remaining.', 'n(HCl reacted) = n(initial) − n(remaining)', 'Use the mole ratio to find moles of CaCO_3.', 'Convert to a concentration or % by mass.']) },
  { id: 'ss13', dp: '6.3.1', t: 'calc', q: '1.32 g of impure Mg reacts with 100.0 mL of 0.750 M HCl. The leftover acid needs 45.0 mL of 0.250 M NaOH. Find the % Mg by mass (impurities don’t react).',
    a: L(['n(HCl) initial = 0.750 × 0.1000 = 0.0750 mol', 'n(HCl) excess = n(NaOH) = 0.250 × 0.0450 = 0.01125 mol', 'n(HCl) reacted = 0.0750 − 0.01125 = 0.06375 mol', 'Mg + 2HCl → MgCl_2 + H_2, so n(Mg) = 0.06375 ÷ 2 = 0.03188 mol', 'm(Mg) = 0.03188 × 24.31 = 0.775 g', '% Mg = 0.775 ÷ 1.32 × 100 = <b>58.7%</b>']) },
  { id: 'ss14', dp: '6.3.1', t: 'calc', q: 'A sample containing NH_4Cl was warmed with 150.0 mL of 1.00 M NaOH. After all the NH_3 was driven off, the excess NaOH needed 50.00 mL of 0.150 M H_2SO_4. What mass of NH_4Cl was in the sample?',
    a: L(['n(H_2SO_4) = 0.150 × 0.05000 = 0.00750 mol', 'H_2SO_4 + 2NaOH → Na_2SO_4 + 2H_2O, so n(NaOH) excess = 0.0150 mol', 'n(NaOH) initial = 1.00 × 0.1500 = 0.150 mol', 'n(NaOH) reacted = 0.150 − 0.0150 = 0.135 mol', 'NH_4Cl + NaOH → NaCl + NH_3 + H_2O (1 : 1), so n(NH_4Cl) = 0.135 mol', 'm = 0.135 × 53.49 = <b>7.22 g</b>']) },
  { id: 'ss15', dp: '6.3.1', t: 'exam', q: '2023 HSC (5 marks): Fertiliser was boiled with 50.00 mL of 1.124 M NaOH to drive off all the NH_3. The solution was made up to 250.0 mL, and 20.00 mL aliquots were titrated with 0.1102 M HCl (titres 22.65, 22.05, 22.00, 21.95 mL). Find the mass of ammonium ions.',
    a: E('NH_4^+(aq) + OH^-(aq) → NH_3(g) + H_2O(l)') + L(['Concordant titres 22.05, 22.00, 21.95 → average 22.00 mL', 'n(HCl) = 0.02200 × 0.1102 = 2.424 × 10^{-3} mol = n(NaOH) excess in 20.00 mL', 'In 250.0 mL: 2.424 × 10^{-3} × (250.0 ÷ 20.00) = 3.031 × 10^{-2} mol', 'n(NaOH) total = 0.05000 × 1.124 = 5.620 × 10^{-2} mol', 'n(NH_4^+) = 5.620 × 10^{-2} − 3.031 × 10^{-2} = 2.590 × 10^{-2} mol', 'm(NH_4^+) = 2.590 × 10^{-2} × 18.042 = <b>0.4672 g</b>']) },
  { id: 'ss16', dp: '6.3.1', t: 'exam', q: '2023 HSC: What volume of 0.540 M HCl will react completely with 1.34 g of sodium carbonate?',
    a: L(['2HCl + Na_2CO_3 → 2NaCl + CO_2 + H_2O', 'n(Na_2CO_3) = 1.34 ÷ 105.99 = 0.0126 mol', 'n(HCl) = 2 × 0.0126 = 0.0253 mol', 'V = 0.0253 ÷ 0.540 = 0.0468 L = <b>46.8 mL</b>']) },
  { id: 'ss17', dp: '6.3.1', t: 'exam', q: '2024 HSC: Ascorbic acid (M = 176.124 g mol^{-1}) in solution A was titrated with KOH. 25.00 mL of A needed 17.50 mL. 25.00 mL of A plus 50.00 mg of ascorbic acid needed 33.10 mL. Find [ascorbic acid] in A.',
    a: L(['The added 50.00 mg used 33.10 − 17.50 = 15.60 mL of KOH', 'So the 17.50 mL titre corresponds to 50.00 × 17.50 ÷ 15.60 = 56.09 mg in 25.00 mL of A', 'n = 0.05609 ÷ 176.124 = 3.185 × 10^{-4} mol', 'c = 3.185 × 10^{-4} ÷ 0.02500 = <b>1.274 × 10^{-2} mol L^{-1}</b>']) }
]});

/* ---------- Deck 10 ---------- */
M6_DECKS.push({ id: 'm6-tc', fa: 'fa3', title: 'Titration curves and choosing indicators', dps: ['6.3.2', '6.3.3'], cards: [
  { id: 'tc01', dp: '6.3.2', t: 'def', q: 'What is a titration curve, and what changes its shape?',
    a: P('A plot of the pH of the solution (y-axis) against the volume of titrant added (x-axis). Its shape depends on:') + OL(['the combination: strong or weak acid with strong or weak base', 'which solution is the unknown in the flask and which is added from the burette']), v: 'curves4' },
  { id: 'tc02', dp: '6.3.2', t: 'con', q: 'Describe and explain the curve when 1 M HCl is added to 1 M NaOH.',
    a: L(['Starts at pH 14.', 'Little change at first because OH^- is in vast excess.', 'Near equivalence, one drop changes the pH from about 10 to 4.', 'Equivalence point at pH 7: only Na^+, Cl^- and water are present.', 'After equivalence the pH falls, then levels out as H_3O^+ is in vast excess.']) + N('Bromothymol blue suits this titration: its colour change (end point) matches the equivalence point.'), v: 'curve:sasb' },
  { id: 'tc03', dp: '6.3.2', t: 'con', q: 'Describe and explain the curve when 1 M HCl is added to 1 M NH_3.',
    a: L(['Starts lower than with NaOH: NH_3 is weak and only partially ionises (NH_3 + H_2O ⇌ OH^- + NH_4^+).', 'Initial drop as H_3O^+ reacts with the few OH^- present.', 'Then it flattens: removing OH^- shifts the equilibrium right, replenishing OH^-. A buffer forms.', 'Near equivalence the NH_3 is used up, the buffer fails and the pH drops sharply (about 8 to 3).', 'Equivalence point < 7 because NH_4^+ is a weak acid: NH_4^+ + H_2O → NH_3 + H_3O^+']), v: 'curve:sawb' },
  { id: 'tc04', dp: '6.3.2', t: 'con', q: 'Describe and explain the curve when 1 M CH_3COOH is added to 1 M NaOH.',
    a: L(['Starts at pH 14; little change at first because OH^- is in vast excess.', 'Near equivalence, a small volume changes the pH from about 10 to 7.5.', 'At equivalence the solution contains Na^+ and CH_3COO^- (sodium ethanoate is soluble).', 'Equivalence point > 7 because ethanoate is a weak base: CH_3COO^- + H_2O → CH_3COOH + OH^-']), v: 'curve:wasb' },
  { id: 'tc05', dp: '6.3.2', t: 'con', q: 'What does a weak acid + weak base titration curve look like, and why are these titrations avoided?',
    a: E('CH_3COOH(aq) + NH_3(aq) → NH_4^+(aq) + CH_3COO^-(aq)') + P('There is no clear pH change at the equivalence point, so an indicator can’t help find it.'), v: 'curve:wawb' },
  { id: 'tc06', dp: '6.3.2', t: 'con', q: 'How can you predict whether a salt solution is acidic, basic or neutral? Classify NaCl, NH_4Cl and CH_3COONa.',
    a: L(['Think about the acid and base that made it: a strong acid or base gives a neutral conjugate; a weak acid gives a weak conjugate base; a weak base gives a weak conjugate acid.', 'NaCl (HCl + NaOH): <b>neutral</b>', 'NH_4Cl (HCl + NH_3): <b>acidic</b>, since NH_4^+ is a weak acid', 'CH_3COONa (CH_3COOH + NaOH): <b>basic</b>, since CH_3COO^- is a weak base']) },
  { id: 'tc07', dp: '6.3.2', t: 'rec', q: 'What is the pH at the equivalence point for each titration combination?',
    a: L(['Strong acid + strong base → neutral products → <b>≈ 7</b>', 'Strong acid + weak base → weak acid product → <b>< 7</b>', 'Weak acid + strong base → weak base product → <b>> 7</b>']) + N('At the equivalence point only products are present, so the pH depends on the conjugates formed.') },
  { id: 'tc08', dp: '6.3.2', t: 'rec', q: 'Which indicator suits each type of titration?', a: '', v: 'indchoice' },
  { id: 'tc09', dp: '6.3.2', t: 'con', q: 'How can a titration curve tell you whether an indicator is suitable?',
    a: P('If the pH of the indicator’s colour change falls on the <b>vertical section</b> of the curve, it’s generally suitable: a single drop causes the entire vertical drop in pH.') + L(['Strong acid + strong base: change ≈ pH 4–10, so bromothymol blue, phenolphthalein or methyl orange', 'Strong acid + weak base: ≈ pH 3–7, so methyl orange', 'Weak acid + strong base: ≈ pH 7–11, so phenolphthalein']), v: 'curve:bands' },
  { id: 'tc10', dp: '6.3.2', t: 'con', q: 'What does the titration curve of a polyprotic acid look like?',
    a: P('Each acidic proton has its own equivalence point. A weak diprotic acid such as carbonic acid (H_2CO_3) shows two; triprotic phosphoric acid (H_3PO_4) shows three.'), v: 'img:diprotic' },
  { id: 'tc11', dp: '6.3.2', t: 'eq', q: 'Why does titrating Na_2CO_3 with HCl give two equivalence points?',
    a: P('Bases that accept several protons do so step by step:') + E('Step 1: Na_2CO_3 + HCl → NaHCO_3 + NaCl') + E('Step 2: NaHCO_3 + HCl → H_2CO_3 + NaCl') + P('Overall: Na_2CO_3 + 2HCl → H_2CO_3 + 2NaCl. The first equivalence point falls in phenolphthalein’s range; the second in bromocresol green’s.'), v: 'img:na2co3' },
  { id: 'tc12', dp: '6.3.3', t: 'con', q: 'Use particle diagrams to model neutralisation of (a) HCl by NaOH and (b) CH_3COOH by NaOH.',
    a: L(['(a) HCl and NaOH are entirely ions. Products: Na^+ and Cl^- ions plus H_2O molecules.', '(b) CH_3COOH is mostly intact molecules. Products: Na^+ and CH_3COO^- ions plus H_2O. Some CH_3COO^- reacts with water (CH_3COO^- + H_2O ⇌ CH_3COOH + OH^-), so a few CH_3COOH molecules and OH^- ions are also present.']), v: 'neutparticles' },
  { id: 'tc13', dp: '6.3.2', t: 'exam', q: '2023 HSC: Two solutions of equal concentration produced this titration curve. Which combination does it represent?', vf: 'curve:hsc23',
    a: P('<b>Addition of a strong acid to a weak base.</b>') + L(['Starting pH is about 11, not 14: the flask holds a weak base.', 'pH falls, so acid is being added.', 'Equivalence point below 7 and a low final pH: the titrant is a strong acid.']) }
]});

/* ---------- Deck 11 ---------- */
M6_DECKS.push({ id: 'm6-ct', fa: 'fa3', title: 'Conductometric titrations', dps: ['6.3.2'], cards: [
  { id: 'ct01', dp: '6.3.2', t: 'con', q: 'When might an indicator be unsuitable for finding the equivalence point?',
    a: L(['Highly coloured unknowns', 'No indicator with a suitable end point', 'Titrating weak acids with weak bases', 'The imprecision of a subjective colour judgement', 'Non-acid–base reactions']) + P('pH or conductivity probes help here, and show the progress of the titration, not just the end point.') },
  { id: 'ct02', dp: '6.3.2', t: 'def', q: 'What is a conductometric titration? Why does conductivity change during one?',
    a: L(['A titration that measures changes in conductivity to find the equivalence point.', 'Conductivity depends on the concentration of ions, and on the ions themselves (their charge and radius).', 'Hydronium and hydroxide ions are small and highly mobile, so they conduct very well.', 'During the titration they’re replaced by less conductive ions, so conductivity changes.']) },
  { id: 'ct03', dp: '6.3.2', t: 'rec', q: 'What are the advantages of conductometric titrations?',
    a: P('They can be used:') + L(['with very dilute solutions', 'when species are at trace levels', 'with coloured or turbid solutions', 'when the reactions are relatively incomplete', 'for acid–base, redox, precipitation and non-aqueous titrations']) },
  { id: 'ct04', dp: '6.3.2', t: 'con', q: 'What factors affect the conductivity of a solution?',
    a: L(['<b>Concentration of ions</b>: strong acids and bases (fully ionised) conduct more than weak; concentrated solutions more than dilute', '<b>Ion size</b>: larger ions are less mobile, so conductivity decreases', '<b>Temperature</b>: higher temperature makes ions more mobile, so conductivity increases']) },
  { id: 'ct05', dp: '6.3.2', t: 'con', q: 'Why do H^+ and OH^- have such high conductivity?',
    a: P('They can ‘<b>proton hop</b>’. Instead of slowly swimming through the liquid, they transfer charge almost instantly across networks of hydrogen-bonded water molecules, so they move much faster than typical ions.') },
  { id: 'ct06', dp: '6.3.2', t: 'con', q: 'Explain the conductivity graph when NaOH is added to HCl.',
    a: E('HCl + NaOH → Na^+ + Cl^- + H_2O') + L(['Start: high (H^+ and Cl^-, and H^+ is very conductive).', 'Before equivalence: H^+ is removed and replaced by less mobile Na^+, so conductivity falls.', 'Equivalence: minimum; only Na^+ and Cl^- are present.', 'After: excess Na^+ and highly mobile OH^- build up, so conductivity rises.']), v: 'cond:sasb' },
  { id: 'ct07', dp: '6.3.2', t: 'con', q: 'Explain the conductivity graph when NH_3 is added to HCl.',
    a: E('HCl + NH_3 → Cl^- + NH_4^+') + L(['Before equivalence: H^+ is replaced by NH_4^+, which is far less conductive, so conductivity falls.', 'After equivalence: excess NH_3 only partially ionises and mostly stays as NH_3, so there’s little or no increase in conductance.']), v: 'cond:sawb' },
  { id: 'ct08', dp: '6.3.2', t: 'con', q: 'Explain the conductivity graph when NaOH is added to CH_3COOH.',
    a: E('CH_3COOH + NaOH → CH_3COO^- + Na^+ + H_2O') + L(['Start: low, because most CH_3COOH doesn’t dissociate.', 'Before equivalence: increases gradually as ions form through neutralisation.', 'After equivalence: increases significantly because excess NaOH fully ionises.', 'The equivalence point is where the trend leaves the line of best fit, so it can be harder to find.']), v: 'cond:wasb' },
  { id: 'ct09', dp: '6.3.2', t: 'con', q: 'Explain the conductivity graph when NH_3 is added to CH_3COOH.',
    a: E('CH_3COOH + NH_3 → CH_3COO^- + NH_4^+') + L(['Start: low; mostly un-ionised CH_3COOH with only a small amount of H^+ and CH_3COO^-.', 'Before equivalence: conductivity rises as CH_3COO^- and NH_4^+ ions form.', 'After equivalence: roughly flat. Excess NH_3 is a weak base, so it ionises to only a very small degree (NH_3 + H_2O ⇌ OH^- + NH_4^+).']), v: 'cond:wawb' },
  { id: 'ct10', dp: '6.3.2', t: 'exam', q: '2024 HSC (4 marks): Ammonia solution is added to hydrochloric acid, giving this graph. Relative conductivities: H^+ 4.76, OH^- 2.70, Cl^- 1.04, NH_4^+ 1.00. Explain the shape, with two balanced equations.', vf: 'cond:hsc24',
    a: E('NH_3(aq) + HCl(aq) → NH_4^+(aq) + Cl^-(aq)') + L(['Before equivalence, highly conductive H^+ (4.76) is replaced by NH_4^+ (1.00), so conductivity falls steadily.', 'At the equivalence point (the minimum) only NH_4^+ and Cl^- remain.', 'After equivalence, the added NH_3 is a weak base that ionises only slightly:']) + E('NH_3(aq) + H_2O(l) ⇌ NH_4^+(aq) + OH^-(aq)') + P('Very few extra ions form, so conductivity stays almost constant, rising only slightly.') },
  { id: 'ct11', dp: '6.3.2', t: 'exam', q: '2022 HSC: 25.00 mL of 0.1131 M HCl was titrated with ammonia. Conductivity fell until 10.0 mL had been added, then stayed constant. What was [NH_3]?',
    a: L(['Equivalence point = where the line levels off: 10.0 mL', 'n(HCl) = 0.1131 × 0.02500 = 2.828 × 10^{-3} mol = n(NH_3) (1 : 1)', 'c(NH_3) = 2.828 × 10^{-3} ÷ 0.0100 = <b>0.283 mol L^{-1}</b>']) }
]});

/* ---------- Deck 12 ---------- */
M6_DECKS.push({ id: 'm6-ka', fa: 'fa3', title: 'Ka, pKa and Kb', dps: ['6.3.4'], cards: [
  { id: 'ka01', dp: '6.3.4', t: 'def', q: 'Write the K_{a} expression for a generic weak acid HA. Why is K_{a} more useful than % ionisation?',
    a: E('HA ⇌ H^+ + A^-') + E('K_{a} = ' + F('[H^+][A^-]', '[HA]')) + P('K_{a} classifies acids quantitatively by how much they dissociate. Unlike percentage ionisation, it doesn’t vary with concentration.') },
  { id: 'ka02', dp: '6.3.4', t: 'con', q: 'How do K_{a} values differ between strong and weak acids?',
    a: L(['Strong acids: equilibrium very far right (essentially 100% products, hence a one-way arrow); very large K_{a}, generally > 100', 'Weak acids: equilibrium largely on the reactant side; small to very small K_{a}, generally < 1', 'Smaller K_{a} → equilibrium further left → <b>weaker</b> acid; larger K_{a} → further right → <b>stronger</b>']) },
  { id: 'ka03', dp: '6.3.4', t: 'def', q: 'Define pK_{a}. How does it relate to acid strength?',
    a: E('pK_{a} = −log_{10}K_{a}') + E('K_{a} = 10^{−pK_{a}}') + L(['K_{a} values range hugely, from 4.8 × 10^{-11} (HCO_3^-) to 3.2 × 10^{9} (HI), so a log scale makes them manageable, just like pH.', '<b>Smaller pK_{a} = stronger acid</b>; larger pK_{a} = weaker acid.']) },
  { id: 'ka04', dp: '6.3.4', t: 'con', q: 'What is the HSC cut-off for a strong acid? Is acetic acid (K_{a} = 1.8 × 10^{-5}) strong?',
    a: L(['For the HSC: any acid with <b>pK_{a} < 0</b> is strong.', 'pK_{a} = −log(1.8 × 10^{-5}) = 4.74, so acetic acid is <b>weak</b>.']) + N('Sources differ. Some define strong as fully ionised past detection (> 99.9%), pK_{a} < −2; others say it must be stronger than H_3O^+, whose pK_{a} is −1.74 or 0 depending on the calculation.') },
  { id: 'ka05', dp: '6.3.4', t: 'con', q: 'What assumptions are made in weak monoprotic acid calculations?',
    a: L(['[H_3O^+] = [A^-]: the only source of H_3O^+ is the acid (self-ionisation of water is ignored)', 'Equilibrium [HA] = initial [HA]: so little has ionised that it’s essentially unchanged', 'The second assumption only holds for weak acids whose initial concentration is much larger than K_{a}']) },
  { id: 'ka06', dp: '6.3.4', t: 'eq', q: 'How is % dissociation calculated?',
    a: E('% dissociation = ' + F('[A^-]', '[HA]') + ' × 100') },
  { id: 'ka07', dp: '6.3.4', t: 'calc', q: 'K_{a} for ethanoic acid is 1.7 × 10^{-5}. For a 0.50 M solution, calculate pK_{a} and pH.',
    a: L(['pK_{a} = −log(1.7 × 10^{-5}) = <b>4.77</b> (the slide rounds this to 4.76)', 'CH_3COOH + H_2O ⇌ CH_3COO^- + H_3O^+; ICE: I 0.50, 0, 0; C −s, +s, +s; E 0.50 − s, s, s', 'K_{a} = s^2 ÷ (0.50 − s) ≈ s^2 ÷ 0.50 (weak acid: 0.50 − s ≈ 0.50)', 's^2 = 1.7 × 10^{-5} × 0.50 = 8.5 × 10^{-6}, so s = [H_3O^+] = 2.9 × 10^{-3} M', 'pH = −log(2.9 × 10^{-3}) = <b>2.54</b>']) },
  { id: 'ka08', dp: '6.3.4', t: 'calc', q: 'Find the % dissociation of 0.50 M ethanoic acid (K_{a} = 1.7 × 10^{-5}), given [H_3O^+] = 2.9 × 10^{-3} M.',
    a: L(['[CH_3COO^-] = [H_3O^+] = 2.9 × 10^{-3} M', '% dissociation = (2.9 × 10^{-3} ÷ 0.50) × 100 = <b>0.58%</b>']) },
  { id: 'ka09', dp: '6.3.4', t: 'calc', q: 'Calculate K_{a} for 0.01 M methanoic acid (HCOOH), which has a pH of 2.9.',
    a: L(['HCOOH(aq) + H_2O(l) ⇌ HCOO^-(aq) + H_3O^+(aq)', '[H_3O^+] = 10^{-2.9} ≈ 0.001 mol L^{-1}', 'ICE: I 0.01, 0, 0; C −0.001, +0.001, +0.001; E 0.009, 0.001, 0.001', 'K_{a} = [HCOO^-][H_3O^+] ÷ [HCOOH] = <b>2 × 10^{-4}</b>']) + N('Keep the unrounded 10^{-2.9} = 1.26 × 10^{-3} in your calculator: it gives 1.8 × 10^{-4} ≈ 2 × 10^{-4}, matching the slide.') },
  { id: 'ka10', dp: '6.3.4', t: 'def', q: 'Write the K_{b} expression for a weak base, and define pK_{b}.',
    a: E('A^-(aq) + H_2O(l) ⇌ HA(aq) + OH^-(aq)') + E('K_{b} = ' + F('[HA][OH^-]', '[A^-]')) + E('pK_{b} = −log_{10}K_{b}') },
  { id: 'ka11', dp: '6.3.4', t: 'con', q: 'Rank ammonia, ethanoate and methanamine from strongest to weakest base.',
    a: P('<b>Methanamine > ammonia > ethanoate.</b> Larger K_{b} (smaller pK_{b}) means a stronger base.'), v: 'kbtable' },
  { id: 'ka12', dp: '6.3.4', t: 'eq', q: 'Write the equations for NH_4^+, HCOOH and HCN acting as acids in water.',
    a: E('NH_4^+(aq) + H_2O(l) ⇌ NH_3(aq) + H_3O^+(aq)') + E('HCOOH(aq) + H_2O(l) ⇌ HCOO^-(aq) + H_3O^+(aq)') + E('HCN(aq) + H_2O(l) ⇌ CN^-(aq) + H_3O^+(aq)') },
  { id: 'ka13', dp: '6.3.4', t: 'eq', q: 'Write the equations for NH_3, CH_3COO^- and CN^- acting as bases in water.',
    a: E('NH_3(aq) + H_2O(l) ⇌ NH_4^+(aq) + OH^-(aq)') + E('CH_3COO^-(aq) + H_2O(l) ⇌ CH_3COOH(aq) + OH^-(aq)') + E('CN^-(aq) + H_2O(l) ⇌ HCN(aq) + OH^-(aq)') },
  { id: 'ka14', dp: '6.3.4', t: 'exam', q: '2024 HSC: A 0.1 M acid titrated with NaOH shows two equivalence points and starts at pH ≈ 1.5–1.7. Two diprotic options: Acid 3 (pK_{a1} = 1.91) and Acid 4 (pK_{a1} = 4.11). Which is it?',
    a: L(['Two equivalence points means a diprotic acid, ruling out the monoprotic options.', 'Acid 3: K_{a1} = 10^{-1.91} = 1.23 × 10^{-2}. Acid 4: K_{a1} = 10^{-4.11} = 7.76 × 10^{-5}.', 'Larger pK_{a} (smaller K_{a}) = weaker acid, so Acid 4 is much weaker than Acid 3.', 'The curve starts quite low (pH 1.5–1.7), so <b>Acid 3</b> is more likely.', 'You can confirm it: at the half-equivalence point, pH = pK_{a}.']) }
]});

/* ---------- Deck 13 ---------- */
M6_DECKS.push({ id: 'm6-bf', fa: 'fa3', title: 'Buffers', dps: ['6.3.7', '6.3.8'], cards: [
  { id: 'bf01', dp: '6.3.7', t: 'def', q: 'What is a buffer solution?',
    a: P('A solution able to <b>resist a change in pH</b> when small amounts of acid or base are added. It doesn’t stop the pH changing completely, but reduces the size of the change compared with an unbuffered solution.') },
  { id: 'bf02', dp: '6.3.7', t: 'rec', q: 'Give examples of where buffers are important.',
    a: L(['Medicines: maintain stability and effectiveness', 'Food: preserve flavour and colour; also used in wine fermentation and stages of textile dyeing', 'The human body: keep blood pH tightly between 7.35 and 7.45']) },
  { id: 'bf03', dp: '6.3.7', t: 'def', q: 'What does a buffer contain? How are acidic and basic buffers made?',
    a: P('Both members of a <b>conjugate acid–base pair</b>, which react with added acid or base.') + L(['<b>Acidic buffer</b> (pH < 7): a weak acid + a soluble salt containing its conjugate base', '<b>Basic buffer</b> (pH > 7): a weak base + a soluble salt containing its conjugate acid']) + N('The weak acid (or base) sets the general pH range; the exact pH depends on the ratio of the conjugate pair.') },
  { id: 'bf04', dp: '6.3.7', t: 'eq', q: 'Explain the ethanoic acid / sodium ethanoate buffer using equations.',
    a: E('CH_3COOH + H_2O ⇌ CH_3COO^- + H_3O^+') + P('Weak acid: only some dissociates.') + E('CH_3COONa → CH_3COO^- + Na^+') + P('Soluble salt: dissociates fully.') + P('The mixture contains large amounts of both CH_3COOH and CH_3COO^-, which lets it resist pH changes. With equimolar concentrations, pH ≈ 4.76.') },
  { id: 'bf05', dp: '6.3.7', t: 'eq', q: 'Explain the ammonia / ammonium chloride buffer using equations.',
    a: E('NH_3 + H_2O ⇌ NH_4^+ + OH^-') + E('NH_4Cl → NH_4^+ + Cl^-') + P('The solution contains large amounts of NH_3 (weak base) and NH_4^+ (its conjugate acid). With equimolar concentrations, pH ≈ 9.25.') },
  { id: 'bf06', dp: '6.3.7', t: 'rec', q: 'What are the effective pH ranges of common buffer pairs?', a: '', v: 'buftable' },
  { id: 'bf07', dp: '6.3.7', t: 'con', q: 'Is the hydrogen phosphate / phosphate buffer acidic or basic? How can you tell?',
    a: E('HPO_4^{2-} + H_2O ⇌ PO_4^{3-} + H_3O^+') + L(['Check the pK_{a} of the weak acid: HPO_4^{2-} has pK_{a} = 12.35.', 'pH = pK_{a} at equal concentrations, so it’s a <b>basic</b> buffer.', 'More conjugate base raises the pH; more acid lowers it.']) },
  { id: 'bf08', dp: '6.3.7', t: 'con', q: 'What job does each component of a buffer do?',
    a: L(['The <b>weak acid</b> removes added OH^-.', 'The <b>conjugate base</b> removes added H_3O^+.']) + P('Both are present together, so the buffer reacts with added H_3O^+ or OH^- before they can significantly change the pH.'), v: 'bufmech' },
  { id: 'bf09', dp: '6.3.7', t: 'con', q: 'Using Le Châtelier’s principle, explain what happens when a strong acid is added to an ethanoic acid / ethanoate buffer.',
    a: E('CH_3COOH(aq) + H_2O(l) ⇌ CH_3COO^-(aq) + H_3O^+(aq)') + L(['Adding strong acid increases [H_3O^+]: a change is imposed on the system.', 'The system counteracts it: the reverse reaction, which uses up H_3O^+, is favoured, so the equilibrium shifts <b>left</b>.', 'The plentiful CH_3COO^- reacts with the extra H_3O^+ to form more CH_3COOH.', '[H_3O^+] doesn’t return all the way to its original value, but the pH change is very small.']) },
  { id: 'bf10', dp: '6.3.7', t: 'con', q: 'What happens when a strong base is added to an ethanoic acid / ethanoate buffer?',
    a: E('CH_3COOH(aq) + OH^-(aq) ⇌ CH_3COO^-(aq) + H_2O(l)') + L(['The added OH^- reacts with the weak acid.', 'This produces water and more conjugate base (CH_3COO^-).', 'Most of the OH^- is removed, so the pH increases only slightly.']) },
  { id: 'bf11', dp: '6.3.7', t: 'def', q: 'What is buffer capacity, and what happens once it’s exceeded?',
    a: L(['Buffer capacity: how much acid or base a buffer can neutralise before its pH changes significantly.', 'Each addition of acid converts some conjugate base into weak acid: CH_3COO^- + H_3O^+ ⇌ CH_3COOH + H_2O.', 'Once most of the CH_3COO^- is used up, the buffer can’t remove added acid and the pH drops rapidly.']), v: 'img:buffer_cap' },
  { id: 'bf12', dp: '6.3.7', t: 'con', q: 'How do concentration and the acid : base ratio affect a buffer?',
    a: L(['<b>Higher concentration</b> of both components gives greater capacity: a buffer 10× more concentrated neutralises far more acid or base. Its pH barely changes.', '<b>Equal concentrations</b> of weak acid and conjugate base make the buffer most effective, with similar amounts available to neutralise added acid or base.', 'Much more weak acid than conjugate base: resists added base far better than added acid (and vice versa).']) },
  { id: 'bf13', dp: '6.3.7', t: 'con', q: 'Where is the buffer region on the curve for HF titrated with NaOH, and what happens at half-equivalence?',
    a: E('HF(aq) + OH^-(aq) → F^-(aq) + H_2O(l)') + L(['Start: only HF, so no effective buffer (just a tiny amount of F^-). The pH isn’t very low because HF is weak.', 'As NaOH is added, HF and F^- both build up: a buffer forms. The flat <b>buffer region</b> shows small pH changes for large volumes of titrant.', '<b>Half-equivalence</b>: [HA] = [A^-], pH = pK_{a}, greatest buffer capacity.', 'Beyond that the buffer becomes less effective; near equivalence little HF remains and the pH changes rapidly.']), v: 'curve:buffer' },
  { id: 'bf14', dp: '6.3.7', t: 'con', q: 'Why can a very acidic or very basic solution seem to act like a buffer? How can you tell it isn’t one?',
    a: L(['pH is logarithmic: a lot of strong acid or base is needed to shift pH to very low or high levels, so a small addition barely changes it. That isn’t a buffer.', 'In a true buffer, [H^+] or [OH^-] changes by <b>significantly less</b> than the amount of acid or base added.']) },
  { id: 'bf15', dp: '6.3.7', t: 'calc', q: 'State the link between K_{a} and K_{b} for a conjugate pair. Find K_{a} of NH_4^+ given K_{b}(NH_3) = 1.8 × 10^{-5}.',
    a: E('K_{a} × K_{b} = K_{w} = 1.0 × 10^{-14} (25 °C)') + L(['Only applies to a conjugate pair: CH_3COOH/CH_3COO^- and NH_4^+/NH_3 work; CH_3COOH/NH_3 doesn’t.', 'K_{a} = 1.0 × 10^{-14} ÷ 1.8 × 10^{-5} = <b>5.6 × 10^{-10}</b>', 'NH_3 is a weak base, so its conjugate acid NH_4^+ is weak too: a small K_{a} is expected.']) },
  { id: 'bf16', dp: '6.3.7', t: 'eq', q: 'State the Henderson–Hasselbalch equation and what it tells you.',
    a: E('pH = pK_{a} + log ' + F('[A^-]', '[HA]')) + L(['[HA] = concentration of weak acid; [A^-] = concentration of its conjugate base', 'pH depends on the <b>ratio</b> of [A^-] to [HA], not on the concentrations themselves', 'Doubling or halving both doesn’t change the pH, but doubling increases buffer capacity']) + P('Basic buffer form: pOH = pK_{b} + log([BH^+] ÷ [B])') },
  { id: 'bf17', dp: '6.3.7', t: 'con', q: 'Why does pH = pK_{a} at the half-equivalence point of a weak acid–strong base titration?',
    a: L(['At half-equivalence, [A^-] = [HA], so [A^-] ÷ [HA] = 1', 'log(1) = 0, so the Henderson–Hasselbalch equation becomes pH = pK_{a}']) + N('One of the most useful shortcuts: read pK_{a} straight off a titration curve at half the equivalence volume.') },
  { id: 'bf18', dp: '6.3.8', t: 'con', q: 'How does the carbonic acid / hydrogen carbonate buffer keep blood pH stable?',
    a: E('H_2CO_3(aq) + H_2O(l) ⇌ HCO_3^-(aq) + H_3O^+(aq)') + L(['Keeps blood pH at about 7.4, essential for normal enzyme activity and efficient metabolism.', 'Acid added: [H_3O^+] rises, the equilibrium shifts left, consuming H_3O^+ and minimising the pH drop.', 'Base added: OH^- reacts with H_3O^+, lowering its concentration; the equilibrium shifts right, producing H_3O^+ and minimising the pH rise.']) },
  { id: 'bf19', dp: '6.3.8', t: 'con', q: 'How do buffers protect lakes?',
    a: L(['Many lakes contain the carbonic acid / hydrogen carbonate buffer: CO_2 dissolves in water to form carbonic acid, setting it up naturally.', 'Acid rain adds H_3O^+; the buffer reacts with it, reducing the pH change.', 'A stable pH is important for the survival of fish, aquatic plants and other organisms.']) },
  { id: 'bf20', dp: '6.3.7', t: 'prac', q: 'Prac 6.7: How was a buffer prepared and its properties demonstrated?',
    a: L(['Part A: 40 mL of 0.2 M acetic acid + 40 mL of 0.2 M sodium acetate; measure the pH, then split between two beakers.', 'Add 3 drops of 1 M HCl to one beaker, mix with a stirring rod (not the pH probe, it may break) and record the pH; repeat five more times. Do the same with 1 M NaOH in the other beaker.', 'Part B: repeat with 0.2 M ammonia + 0.2 M ammonium chloride.', 'Part C: repeat with 1 × 10^{-4} M HCl + 0.1 M NaCl for comparison; this is not a buffer pair.']) }
]});

